<?php defined('ABSPATH') || exit;get_header(); ?>
<main id="main"><?php while(have_posts()):the_post(); ?>
<article <?php post_class('journal-article'); ?>>
<header class="article-heading container"><nav class="article-breadcrumb" aria-label="Breadcrumb"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a><span>/</span><a href="<?php echo esc_url(mm_journal_url()); ?>">Journal</a></nav><?php mm_post_meta(); ?><h1><?php the_title(); ?></h1><p class="article-deck"><?php echo esc_html(get_the_excerpt()); ?></p></header>
<?php if(has_post_thumbnail()): ?><figure class="article-cover container"><?php the_post_thumbnail('large',['fetchpriority'=>'high','alt'=>mm_journal_image_alt()]); ?><figcaption>Original illustrative watch imagery · MUNEEB MART Journal</figcaption></figure><?php endif; ?>
<?php [$article,$sections]=mm_article_sections(apply_filters('the_content',get_the_content())); ?>
<div class="article-layout container"><aside class="article-sidebar"><?php if(count($sections)>=4): ?><details class="article-toc" open><summary>In this article</summary><ol><?php foreach($sections as $section)if($section['level']==='2')echo '<li><a href="#'.esc_attr($section['id']).'">'.esc_html($section['label']).'</a></li>'; ?></ol></details><?php endif; ?><p>Explore your own sense of style.</p><a class="text-link" href="<?php echo esc_url(home_url('/collections/')); ?>">The collections →</a></aside><div class="article-body editor-content"><?php echo $article; // Content passes through WordPress filters; headings are escaped above. ?>
<div class="article-share"><span>Share this article</span><a rel="noopener noreferrer" target="_blank" href="<?php echo esc_url('https://www.facebook.com/sharer/sharer.php?u='.rawurlencode(get_permalink())); ?>">Facebook ↗</a><a rel="noopener noreferrer" target="_blank" href="<?php echo esc_url('https://wa.me/?text='.rawurlencode(get_the_title().' '.get_permalink())); ?>">WhatsApp ↗</a><a href="<?php echo esc_url('mailto:?subject='.rawurlencode(get_the_title()).'&body='.rawurlencode(get_permalink())); ?>">Email ↗</a></div>
<?php the_tags('<p class="article-tags">Topics: ',', ','</p>'); ?><div class="article-author"><p class="eyebrow">FROM THE EDITORIAL DESK</p><h2><?php the_author(); ?></h2><p>Practical ideas for choosing, wearing and caring for a watch. Articles provide general editorial guidance; the exact model’s verified instructions take priority.</p></div>
<?php the_post_navigation(['prev_text'=>'<span>Previous article</span>%title','next_text'=>'<span>Next article</span>%title']); ?></div></div>
</article>
<?php $cats=wp_get_post_categories(get_the_ID());$related=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>[get_the_ID()],'orderby'=>'date','ignore_sticky_posts'=>true,'no_found_rows'=>true,'category__in'=>$cats]);if(!$related->have_posts())$related=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>[get_the_ID()],'ignore_sticky_posts'=>true,'no_found_rows'=>true]);if($related->have_posts()): ?><section class="section container"><div class="section-heading"><div><p class="eyebrow">ANOTHER PERSPECTIVE</p><h2>Continue the story.</h2></div></div><div class="journal-grid"><?php while($related->have_posts()):$related->the_post();mm_journal_card();endwhile;wp_reset_postdata(); ?></div></section><?php endif; ?>
<?php $recommended=get_post_meta(get_the_ID(),'_mm_recommend_collections',true);if($recommended): ?><section class="section container"><div class="section-heading"><div><p class="eyebrow">FROM THE COLLECTION</p><h2>Explore the look.</h2></div><a class="text-link" href="<?php echo esc_url(home_url('/catalog/')); ?>">Shop all watches →</a></div><?php mm_products(['category'=>array_map('sanitize_title',(array)$recommended),'limit'=>4]); ?><p class="demo-caption">Illustrative products and prices. Read verified specifications before a real purchase.</p></section><?php endif; ?>
<?php endwhile; ?></main><?php get_footer(); ?>
